INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00040', NULL, 'https://nordicwelfare.org/en/deafblindness/', NULL, NULL, NULL, NULL, 'Nordic Deafblind Field framework — Nordens Välfärdscenter (NVC) deafblind unit. Underpinning: Nordic Definition of Deafblindness (revised 2007 + further refinements): "deafblindness is a distinct disability, a combination of vision + hearing impairment that limits activity + restricts full participation"; classification: congenital vs acquired (USHER syndrome subtypes 1/2/3; CHARGE association; rubella embryopathy). Companion: Deafblind International (DbI) global federation; Helen Keller National Center US; Sense UK; EDBN (European Deafblind Network). Nordic Welfare Centre publishes thematic guidance on built environment (lighting + acoustics + tactile orientation for deafblind), interpreter training, education, employment, ageing. UN CRPD Art. 24(3)(c) + 9 frame Nordic implementation.', NULL, NULL, NULL);
