INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00080', NULL, 'https://www.invalidiliitto.fi/esteettomyys/invalidiliiton-esteettomyystyo/eskeh-kartoitusmenetelma', NULL, NULL, NULL, NULL, 'ESKEH (Esteettömyyskartoitusmenetelmä) — originally developed by ESKEH-projekti 2007-2009 (funded by RAY Raha-automaattiyhdistys + Helsinki kaikille -projekti); 2018 update by Invalidiliitto Esteettömyyskeskus ESKE; companion Luonto-ESKEH (nature trails edition) 2014, updated 2019 + 2024 (Suomen Paralympiakomitea Reitit ja rakenteet project); criteria based on Finnish esteettömyysmääräykset/-ohjeet/-suositukset', NULL, NULL, NULL);
