INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00163', NULL, 'https://www.anah.gouv.fr/proprietaires/maprimeadapt', NULL, NULL, NULL, NULL, 'MaPrimeAdapt'' — effective 1 January 2024 per Décret n° 2023-1258 du 22 décembre 2023; replaces ANAH "Habiter Facile" + CNAV "Habitat et Cadre de vie" + part of crédit d''impôt autonomie; 50% subsidy (modest income) or 70% (very modest); cap €22,000 HT works; eligibility ≥70 yo any GIR / 60-69 yo GIR 1-6 / disability ≥50% or PCH-eligible', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00164', NULL, 'https://www.hdb.gov.sg/residential/living-in-an-hdb-flat/for-our-seniors/ease', NULL, NULL, NULL, NULL, 'EASE Programme — launched July 2012; EASE 2.0 launched 1 April 2024 (expanded set); extended to ~80,000 private homes from 1 April 2026 (age 80+ first round, announced Feb 2026 by National Development Minister Chee Hong Tat). Government subsidy 87.5%–95% cost share (by flat type, 3-room highest). 11 fittings: grab bars (8/10 first toilet, 6 second), slip-resistant floor treatment, ramps (up to 5), lowered toilet entrance kerb, widened toilet entrance, foldable U-profile grab bars, bidet sprays, HFAD (home fire alarm device). Eligibility: Singaporean HDB owner with household member 65+ (or 60-64 with ≥1 ADL need + Functional Assessment Report). ~340,000 households tapped as of January 2025.', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00165', NULL, 'https://www.kfw.de/inlandsfoerderung/Privatpersonen/Bestandsimmobilien/F%C3%B6rderprodukte/Altersgerecht-Umbauen-Kredit-(159)/', NULL, NULL, NULL, NULL, 'KfW-Programm 159 "Altersgerecht Umbauen — Kredit" (since 2009); accompanying KfW 455-B Investitionszuschuss Barrierereduzierung (max €6,250; discontinued Dec 2024) + KfW 455-E Investitionszuschuss Einbruchschutz; reactivated April 2026 with €50M budget', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00166', NULL, 'https://www.husbanken.no/person/tilskudd-til-tilpasning/', NULL, NULL, NULL, NULL, 'Husbanken tilskudd til tilpasning av bolig + Husbankens grunnlån (basic loan with merverdi for life-cycle dwellings); Forskrift om tilskudd til tilpasning av bolig; companion Husbanken livsløpsbolig (life-span housing) framework + bostøtte (housing benefit); underlying Husbankloven; SINTEF Byggforsk + NTNU companion research (Denizou et al. 2019)', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00167', NULL, 'https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/lag-2018222-om-bostadsanpassningsbidrag_sfs-2018-222/', NULL, NULL, NULL, NULL, 'Lag (2018:222) om bostadsanpassningsbidrag — utfärdad 2018-04-19; ändrad t.o.m. SFS 2025:453; companion Förordning (2018:224) om bostadsanpassningsbidrag; Boverket 2023:11 evaluation report; Prop. 2017/18:80, bet. 2017/18:CU6, rskr. 2017/18:210. §3 grant to person with disability for adaptation of permanent dwelling; §4 multi-family home owner takeover provision; §5 grant only for fixed-feature changes necessary for dwelling fitness for purpose', NULL, NULL, NULL);
