INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00170', NULL, 'https://www.gallaudet.edu/campus-design-and-planning/deafspace', NULL, NULL, NULL, NULL, 'DeafSpace Project — Gallaudet University, Washington DC; founded 2005 by Hansel Bauman (architect) in collaboration with Gallaudet ASL Deaf Studies Department; Sorenson Language and Communication Center (SLCC) completed 2008 (architect SmithGroupJJR + Hansel Bauman). DeafSpace Guidelines (DSG) include ~150 design elements across 5 categories: Space and Proximity, Sensory Reach, Mobility and Proximity, Light and Color, Acoustics. Rounded corners + curved-wall principles for sightline preservation + signing-while-walking accommodation; Co-1 self-report category (designer-affiliated evidence ranking).', NULL, NULL, NULL);
