INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00274', NULL, 'https://www.jlconline.com/cost-vs-value/2021/', NULL, NULL, NULL, NULL, 'Remodeling Magazine "Cost vs Value Report" — annual; 28-35 remodeling projects × 119-150 US markets; Universal Design bathroom remodel category introduced 2018+; ROI track: 57.9% (2021), 60.1% midrange bath (2021), ~50.5% (2024), 61.2% (2025, +11pts); pre-pandemic peak ROI ~68-70% — matches DB description "UD bathroom ROI ≈68–70%". Project scope (UD bathroom): 5×7-foot bathroom; wheelchair access; curbless roll-in shower with grab bars + fold-down seat; comfort-height toilet; LVT flooring; universal-design accessories. Companion: ZIP-code level data introduced 2021. Methodology: cost comparison via professional-remodeler panel; resale value via real estate agents/Zonda housing data.', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00275', NULL, 'https://newsroom.accenture.com/news/2018/companies-leading-in-disability-inclusion-have-outperformed-peers-accenture-research-finds', NULL, NULL, NULL, NULL, 'Getting to Equal: The Disability Inclusion Advantage — 17-page research report; 140 companies analyzed via Disability Equality Index (DEI) benchmarking tool over 4 years; identified 45 best-in-class disability-inclusion leaders. Findings: leaders had 28% higher revenue, 2× net income, 30% higher economic profit margins; July 2018 US BLS data: 29% PwD employed (ages 16-64) vs 75% non-disabled; 15.1 million PwD US working-age population; potential GDP boost up to $25 billion with 1% more PwD in labor force. Four-pillar framework: Employ, Enable, Engage, Empower. Companion: Accenture 2024-2025 update report "The disability inclusion imperative" (Disability-Inclusion-Report-Business-Imperative.pdf).', NULL, NULL, NULL);
