INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00277', NULL, 'https://ec.europa.eu/docsroom/documents/5566', NULL, NULL, NULL, NULL, 'Economic Impact and Travel Patterns of Accessible Tourism in Europe — Final Report; 12-month research study commissioned by EC DG ENTR (Enterprise and Industry); 2012 baseline: 17.6 million accessible-tourism trips in EU (7.2M by PwDs + 10.4M by elderly); companion summary report; companion UNWTO 1st Conference on Accessible Tourism in Europe (San Marino 19-20 Nov 2014) DOI 10.18111/9789284417902; underlying OSSATE project (Buhalis + Eichhorn + Michopoulou + Miller 2005, University of Surrey); ENAT (European Network for Accessible Tourism) partnership', 'NO-MATCH', NULL, NULL);
