INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00279', NULL, 'https://www.germany.travel/en/accessible-germany/tourism-for-all-validated-travel-options.html', NULL, NULL, NULL, NULL, 'BMWi accessible-tourism economic-impact study presented 11 September 2008 at BMWi Conference Centre, Berlin (Invalidenstraße). Lead institutions: University of Münster + PROJECT M GmbH; participants from disability organizations + tourism sector; subsequent "Tourism for All" national labelling system. Year correction from DB 2004 → 2008 (original BMWi accessible-tourism study cycle ran 2008+; 2004 may reference a precursor regional study). Companion: "Reisen für Alle" certification scheme (DSFT Berlin operator).', NULL, NULL, NULL);
