INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00292', NULL, 'https://behindthehedges.com/notable-features-of-modern-bathrooms/', NULL, NULL, NULL, NULL, 'Behind The Hedges April 5, 2026 trend article citing: 2026 National Kitchen & Bath Association (NKBA) Trends Report (72% designers report bathroom enlargement for wellness features); Forbes (curbless entries + built-in benches as luxury safety features); Re-Bath designer Jenny Mars (organic-minimalism trend). Low-grade industry-blog provenance; cited in BPC context for "accessibility-as-luxury market repositioning" framing.', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00293', NULL, 'https://mykukun.com/blog/why-accessibility-is-the-highest-roi-renovation', NULL, NULL, NULL, NULL, 'Kukun blog article published April 28 2026 by Alejandro Guerrero — references Joint Center for Housing Studies (JCHS) Harvard projections on accessibility renovation spending; PICO™ Functional Utility score (Kukun proprietary); "Per-Bed" senior-living rental ROI model; cites Independent Living Median rent ($3,065/month 2026) + Senior-Lite assisted-living conversion economics. Low-grade industry-blog provenance; cited in BPC context for "highest-ROI accessibility renovation" market thesis.', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00294', NULL, 'https://www.portseattle.org/page/sensory-friendly-spaces', NULL, NULL, NULL, NULL, 'Sea-Tac Sensory Room case study + design-guidance documentation — North + South Sensory Rooms opened pre-security (Concourse A + Concourse B); design features include adjustable lighting (Co-1 dim-up over 5 min), tactile-textured walls, quiet zone, weighted blanket, fidget tools; partner training program with The Arc of King County. Companion: KultureCity Sensory Inclusive Certification.', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00295', NULL, 'https://www.jchs.harvard.edu/', NULL, NULL, NULL, NULL, 'JCHS five-feature framework widely cited in US housing accessibility analysis; cf. HUD "Accessibility of America''s Housing Stock: Analysis of the 2011 American Housing Survey"', NULL, NULL, NULL);
