INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00304', NULL, 'https://adata.org/faq/it-expensive-make-all-newly-constructed-places-public-accommodation-and-commercial-facilities', NULL, NULL, NULL, NULL, 'ADA National Network "Top ADA Frequently Asked Questions" page (adata.org/faq/it-expensive-make-all-newly-constructed-places-public-accommodation-and-commercial-facilities) — states: "The cost of incorporating accessibility features in new construction is less than one percent of construction costs. This is a small price in relation to the economic benefits to be derived from full accessibility in the future, such as increased employment and consumer spending." Companion: ada.gov + access-board.gov; underlying ADA Title III + 2010 ADA Standards for Accessible Design. Source for the widely-cited <1% new-build accessibility cost premium claim.', NULL, NULL, NULL);
INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00305', NULL, 'https://woodstockinst.org/research/homemod-costs-and-benefits/', NULL, NULL, NULL, NULL, 'Woodstock Institute HUD-funded HomeMod cost-benefit study — Chicago HomeMod Program evaluation; average modification cost $12,200–$15,150/unit; 3-year cost-savings $7,427–$8,891/participant from reduced service use (DB description "$6,668" reflects a different metric window — owner-queue reconciliation); break-even if 2.5–4.6% participants defer assisted living by 5 yrs OR 0.5–1.0% defer nursing home by 8 yrs. Source for U.S. visitable/aging-in-place cost-benefit literature.', NULL, NULL, NULL);
