INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00531', NULL, 'https://accessible.canada.ca/creating-accessibility-standards/can-asc-24-wayfinding-and-signage/10-general-requirements-lighting-and-contrast', NULL, NULL, NULL, NULL, 'CAN-ASC-2.4 Wayfinding and Signage (Accessibility Standards Canada) clause 10 General requirements for lighting and contrast — Table 1 minimum luminance contrast values for matte surfaces; large surfaces ≥40 LRV light surface + ≥30% Michelson + ≥45% Weber; hazards ≥50 LRV + ≥60% Michelson + ≥75% Weber; text ≥70 LRV + ≥60% Michelson + ≥75% Weber. Companion standards: BS 8300-2:2018 Code of practice (UK 30-point LRV minimum); AS 1428.1:2009 + AS 1428.4.1:2009 (Australia 30% luminance contrast minimum via Bowman-Sapolinski equation Y1-Y2). Underlying: Accessible Canada Act (S.C. 2019, c. 10) + UK Equality Act 2010 + Australia DDA + AS/NZS framework. Argument: 30% is regulatory FLOOR, not functional optimum — Canadian Museum for Human Rights (CMHR) Inclusive and Accessible Design Guidelines uses 70% LRV difference for text legibility as best practice.', NULL, NULL, NULL);
