INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-00569', NULL, 'https://www.cabhi.com/blog/dementia-and-noise-how-one-long-term-care-home-is-enhancing-its-sound-environment-to-support-residents-mental-health/', NULL, NULL, NULL, NULL, 'Canadian dementia + noise framework — Shannex Arborstone Halifax NS sound audit pilot 2017; CABHI-supported knowledge-translation project; cites WHO 2011 Burden of disease from environmental noise (EU 27 + Western European DALY estimates: 61,000 yrs ischemic heart disease, 45,000 yrs cognitive impairment in children, 903,000 yrs sleep disturbances, 22,000 yrs tinnitus, 587,000 yrs annoyance); flight-or-fight stress response triggered by abrupt/loud sounds; hyperacusis in PWD reducing capacity to filter sensory input; noise sources in LTC: laundry carts, staff conversations, elevators, dishes. Companion: Christogianni-Filingeri 2022 MS heat sensitivity (REF-00254 framework parallel); IPA International Psychogeriatrics + Centre for Aging + Brain Health Innovation (CABHI Toronto, founded 2015 under Baycrest Hospital). Owner-queue: DB year 2011 likely refers to WHO 2011 EU report rather than the CABHI/Shannex 2017 pilot; pub_year set to 2017 reflecting framework date; original WHO 2011 EU DALY report by World Health Organization Regional Office for Europe.', 'NO-MATCH', NULL, NULL);
