INSERT OR IGNORE INTO source_locators (ref_id, doi, url, pmid, pmcid, isbn, issn, standard_number, doi_resolution_outcome, url_resolution_outcome, url_last_fetched) VALUES ('REF-VERIFIED-001', NULL, 'https://www.huduser.gov/portal/publications/', NULL, NULL, NULL, NULL, 'HUD-PDR-400 series; commissioned alongside Chollet DJ (1979) "A Cost-Benefit Analysis of Accessibility" + Steinfeld E (1979) HUD-PDR-400 Selected Bibliography on Barrier-Free Design; foundational US accessibility-cost research base for ADA 1990, ANSI A117.1 series, Fair Housing Act 1988 amendments. 9 buildings analyzed: high-rise tower, garden apartments, single-family house, college dormitory, convention hall, public branch library, town hall, college classroom, retail shopping center (8 in Syracuse / North Syracuse / Clarkstown / Glen Falls NY + 1 in Detroit MI). Retrofit cost range 0.12-0.5%; original-design cost range 0.006-0.13% (shopping center to college classroom); ~1% commonly cited as conservative upper bound.', NULL, NULL, NULL);
